/**
 * HTTP surface of the budget chronology (Feature A) plus the create-envelope
 * type regression: GET /api/envelopes/versions, the version-carrying bodies of
 * POST /api/budget/edit and POST /api/envelopes/edit, and POST /api/envelopes
 * accepting every non-income envelope type the zod enum allows ("saving" was
 * live-rejected by a pre-remediation deploy; this pins the fixed behaviour).
 * Driven through the real app over the in-memory store, signed in, exactly as
 * the SPA calls it.
 */

import { describe, test, expect } from "bun:test";
import type {
  BudgetVersionsResponse,
  CreateEnvelopeResponse,
  EditBudgetResponse,
  GridResponse,
} from "../src/server/contract.ts";
import { currentPeriod } from "../src/platform/time.ts";
import { monthBounds, nextPeriod, periodKey } from "../src/envelope/period.ts";
import { makeTestApp, postJson, getJson, LOCAL_USER_ID, type TestApp } from "./server-test-app.ts";

const TZ = "Australia/Melbourne";
const NOW = currentPeriod(TZ);
const NEXT = nextPeriod(NOW);
const NEXT_FIRST = monthBounds(NEXT).first;

async function createEnvelope(t: TestApp, cookie: string, body: unknown): Promise<string> {
  const res = await postJson(t.app, "/api/envelopes", body, cookie);
  expect(res.status).toBe(200);
  return ((await res.json()) as CreateEnvelopeResponse).id;
}

async function grid(t: TestApp, cookie: string): Promise<GridResponse> {
  const res = await getJson(t.app, "/api/envelopes", cookie);
  expect(res.status).toBe(200);
  return (await res.json()) as GridResponse;
}

describe("GET /api/envelopes/versions", () => {
  test("requires auth and an envelopeId", async () => {
    const t = await makeTestApp();
    expect((await getJson(t.app, "/api/envelopes/versions?envelopeId=x")).status).toBe(401);
    const cookie = await t.signIn();
    expect((await getJson(t.app, "/api/envelopes/versions", cookie)).status).toBe(400);
    expect((await getJson(t.app, "/api/envelopes/versions?envelopeId=nope", cookie)).status).toBe(404);
  });

  test("a scheduled edit shows in the chronology with computed statuses", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });

    // Schedule the change as of the first of NEXT month (the "1 Aug" case).
    const edit = await postJson(
      t.app,
      "/api/budget/edit",
      { lines: [{ envelopeId: id, amountCents: 60000 }], scope: "ongoing", effectiveFrom: NEXT_FIRST },
      cookie,
    );
    expect(edit.status).toBe(200);
    expect(((await edit.json()) as EditBudgetResponse).changed).toBe(1);

    const res = await getJson(t.app, `/api/envelopes/versions?envelopeId=${id}`, cookie);
    expect(res.status).toBe(200);
    const body = (await res.json()) as BudgetVersionsResponse;
    expect(body.envelopeId).toBe(id);
    expect(body.versions.length).toBe(2);
    // Most recent first: the scheduled 600, then the completed-next-month 500.
    expect(body.versions[0]).toMatchObject({
      amountCents: 60000,
      effectiveFrom: NEXT_FIRST,
      effectiveTo: null,
      status: "scheduled",
    });
    expect(body.versions[1]?.amountCents).toBe(50000);
    expect(body.versions[1]?.status).toBe("active");

    // The CURRENT month's grid still shows the old amount (scheduled = inert now).
    const g = await grid(t, cookie);
    expect(g.rows.find((r) => r.id === id)?.allocationCents).toBe(50000);
  });

  test("an income budget change as of next month versions through the same mechanism", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Salary", type: "income", parentId: null, budgetedCents: 500000, targetCents: 500000 });

    const res = await postJson(
      t.app,
      "/api/envelopes/edit",
      { id, type: "income", budgetedCents: 600000, targetCents: 600000, effectiveFrom: NEXT_FIRST },
      cookie,
    );
    expect(res.status).toBe(200);

    // This month's grid keeps the old income budget.
    const g = await grid(t, cookie);
    expect(g.income.find((i) => i.id === id)?.budgetedCents).toBe(500000);

    // The chronology carries the bootstrapped baseline and the scheduled change.
    const versions = ((await (
      await getJson(t.app, `/api/envelopes/versions?envelopeId=${id}`, cookie)
    ).json()) as BudgetVersionsResponse).versions;
    expect(versions.length).toBe(2);
    expect(versions[0]).toMatchObject({ amountCents: 600000, status: "scheduled" });
    expect(versions[1]).toMatchObject({ amountCents: 500000, status: "active" });

    // Next month's grid resolves to the new figure (query the month explicitly).
    const bounds = monthBounds(NEXT);
    const nextGrid = await getJson(t.app, `/api/envelopes?from=${bounds.first}&to=${bounds.last}`, cookie);
    expect(nextGrid.status).toBe(200);
    const ng = (await nextGrid.json()) as GridResponse;
    expect(ng.period).toBe(periodKey(NEXT));
    expect(ng.income.find((i) => i.id === id)?.budgetedCents).toBe(600000);
  });

  test("completePrevious=false coexists and SUMS in the shared months", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });

    const res = await postJson(
      t.app,
      "/api/budget/edit",
      {
        lines: [{ envelopeId: id, amountCents: 20000 }],
        scope: "ongoing",
        effectiveFrom: NEXT_FIRST,
        completePrevious: false,
      },
      cookie,
    );
    expect(res.status).toBe(200);

    const bounds = monthBounds(NEXT);
    const nextGrid = (await (
      await getJson(t.app, `/api/envelopes?from=${bounds.first}&to=${bounds.last}`, cookie)
    ).json()) as GridResponse;
    expect(nextGrid.rows.find((r) => r.id === id)?.allocationCents).toBe(70000);
  });

  test("a malformed effectiveFrom is a 400, not an engine exception", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const res = await postJson(
      t.app,
      "/api/budget/edit",
      { lines: [], scope: "ongoing", effectiveFrom: "August 1st" },
      cookie,
    );
    expect(res.status).toBe(400);
  });
});

describe("POST /api/envelopes accepts every non-income envelope type (live regression)", () => {
  test("type 'saving' creates cleanly, keeps its type, and materialises its budget", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const res = await postJson(
      t.app,
      "/api/envelopes",
      { name: "Holiday Fund", type: "saving", budgetedCents: 30000, period: "monthly" },
      cookie,
    );
    expect(res.status).toBe(200);
    const created = (await res.json()) as CreateEnvelopeResponse;
    expect(created.type).toBe("saving");

    const g = await grid(t, cookie);
    const row = g.rows.find((r) => r.id === created.id);
    expect(row?.type).toBe("saving");
    // The template line materialised into the current month.
    expect(row?.allocationCents).toBe(30000);
  });

  test("types 'envelope' and 'working' create cleanly too", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    for (const type of ["envelope", "working"] as const) {
      const res = await postJson(t.app, "/api/envelopes", { name: `T ${type}`, type }, cookie);
      expect(res.status).toBe(200);
      expect(((await res.json()) as CreateEnvelopeResponse).type).toBe(type);
    }
    const g = await grid(t, cookie);
    expect(g.rows.find((r) => r.name === "T envelope")?.type).toBe("envelope");
    expect(g.rows.find((r) => r.name === "T working")?.type).toBe("working");
  });
});

describe("grid pending in Spent/Left over HTTP (wire shape)", () => {
  test("a pending non-transfer transaction moves spent/left on its row", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
    const today = `${periodKey(NOW)}-05`;
    await t.store.upsertTransactions(LOCAL_USER_ID, [
      {
        id: "tx-pend",
        date: today,
        amountCents: -2345,
        accountId: "acc-1",
        categoryId: null,
        envelopeId: id,
        payee: "Coles",
        isTransfer: false,
        isPending: true,
        rawJson: "{}",
      },
    ]);
    const g = await grid(t, cookie);
    const row = g.rows.find((r) => r.id === id)!;
    expect(row.leftCents).toBe(50000 - 2345); // pending now counts in the grid
  });
});

