  const res = await this.q<{ id: string; name: string }>(
    `SELECT id, name FROM categories WHERE user_id = $1`,
    [userId],
  );
  return res.rows.map((r) => ({ id: r.id, name: r.name }));
}

async listDismissedCategoryIds(userId: UserId): Promise<string[]> {
  const res = await this.q<{ category_id: string }>(
    `SELECT category_id FROM dismissed_categories WHERE user_id = $1`,
    [userId],
  );
  return res.rows.map((r) => r.category_id);
}

async setCategoryDismissed(userId: UserId, categoryId: string, dismissed: boolean): Promise<void> {
  if (dismissed) {
    await this.q(
      `INSERT INTO dismissed_categories (user_id, category_id, dismissed_at) VALUES ($1, $2, $3)
       ON CONFLICT (user_id, category_id) DO UPDATE SET dismissed_at = excluded.dismissed_at`,
      [userId, categoryId, Date.now()],
    );
  } else {
    await this.q(`DELETE FROM dismissed_categories WHERE user_id = $1 AND category_id = $2`, [userId, categoryId]);
  }
}

