/**
 * HTTP surface of the new-category detection + adopt flow, driven through the
 * real app over the in-memory store, signed in, exactly as the SPA calls it:
 *
 *   GET  /api/categories/unmapped  auth + response shape
 *   POST /api/categories/adopt     creates the envelope AND the mapping atomically,
 *                                  after which the category no longer reads as
 *                                  unmapped and its spend resolves to the envelope.
 */

import { describe, test, expect } from "bun:test";
import type {
  AdoptCategoryResponse,
  GridResponse,
  UnmappedCategoriesResponse,
} from "../src/server/contract.ts";
import type { Tx } from "../src/platform/store.ts";
import { currentPeriod } from "../src/platform/time.ts";
import { monthBounds, periodKey } from "../src/envelope/period.ts";
import { makeTestApp, postJson, getJson, LOCAL_USER_ID, type TestApp } from "./server-test-app.ts";

const TZ = "Australia/Melbourne";
const NOW = currentPeriod(TZ);
const MID = `${periodKey(NOW)}-15`;

function txRaw(id: string, categoryId: string, title: string, amountCents: number, date: string): Tx {
  return {
    id,
    date,
    amountCents,
    accountId: "nab-everyday",
    categoryId,
    envelopeId: null,
    payee: "Payee",
    isTransfer: false,
    isPending: false,
    rawJson: JSON.stringify({ id, category: { id: 99, title }, amount: amountCents / 100 }),
  };
}

async function unmapped(t: TestApp, cookie: string): Promise<UnmappedCategoriesResponse> {
  const res = await getJson(t.app, "/api/categories/unmapped", cookie);
  expect(res.status).toBe(200);
  return (await res.json()) as UnmappedCategoriesResponse;
}

describe("GET /api/categories/unmapped", () => {
  test("requires auth", async () => {
    const t = await makeTestApp();
    expect((await getJson(t.app, "/api/categories/unmapped")).status).toBe(401);
  });

  test("returns the unmapped categories, most transactions first", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    await t.store.upsertTransactions(LOCAL_USER_ID, [
      txRaw("g1", "cat-gym", "Gym", -1500, MID),
      txRaw("g2", "cat-gym", "Gym", -1500, MID),
      txRaw("c1", "cat-coffee", "Coffee", -500, MID),
    ]);
